// Owns the single-file bundle. Offline, deterministic, no deps.
// v0.5 adds the declaration checker to the bundle.
import { readFileSync, writeFileSync } from "node:fs";

const FILES = ["src/glob.mjs", "src/check_exchange.mjs", "src/check_declaration.mjs"];

export function buildBundle() {
  const parts = [];
  parts.push(`#!/usr/bin/env node
// claim-check v0.5 - single file, offline, zero dependencies.
// Generated by src/build_bundle.mjs. Do not edit by hand.
//
// Two units:
//   checkExchange()      - scope conformance over an action-call log
//   verdictForDeclaration() - scope conformance over a DECLARATION (instructions)
//
// Usage:
//   node claim-check.mjs <exchange.json>
//   node claim-check.mjs --declaration <declaration.md>
`);
  for (const f of FILES) {
    let src = readFileSync(new URL("../" + f, import.meta.url), "utf8");
    // strip import/export statements that do not apply inside a single file
    src = src.replace(/^import .*$/gm, "");
    src = src.replace(/^export (const|function|class)/gm, "$1");
    parts.push(`\n// ===== ${f} =====\n${src}`);
  }
  // strip relative imports from stripped sources
  let out = parts.join("\n");
  out = out.replace(/^import .*$/gm, "");

  // CLI footer
  out += `
// ===== CLI =====
import { readFileSync as __rf } from "node:fs";
const __args = process.argv.slice(2);
if (__args.length === 0) {
  console.error("usage: node claim-check.mjs <exchange.json> | --declaration <file.md>");
  process.exit(2);
}
if (__args[0] === "--declaration") {
  const r = verdictForDeclaration(__rf(__args[1], "utf8"));
  console.log(r.verdict);
  for (const c of r.reasons) {
    console.log("  " + c.code);
    for (const cite of c.cites) console.log("    - " + cite);
  }
  process.exitCode = r.verdict === "OUT-OF-SCOPE" ? 1 : 0;
} else {
  const raw = JSON.parse(__rf(__args[0], "utf8"));
  const exchanges = Array.isArray(raw) ? raw : Array.isArray(raw.exchanges) ? raw.exchanges : [raw];
  let outN = 0, und = 0;
  for (const ex of exchanges) {
    const r = checkExchange(ex);
    if (r.verdict === "OUT-OF-SCOPE") outN++;
    if (r.verdict === "UNDECIDABLE") und++;
    console.log(\`\${r.id ?? "(no id)"}\t\${r.verdict}\`);
    for (const c of r.perCall) for (const rs of c.reasons) {
      console.log("  " + rs.code);
      for (const cite of rs.cites) console.log("    - " + cite);
    }
  }
  console.log(\`\\nsummary: \${exchanges.length} exchange(s), \${outN} out-of-scope, \${und} undecidable\`);
  process.exitCode = outN > 0 ? 1 : 0;
}
`;
  return out;
}

if (process.argv[1] && process.argv[1].endsWith("build_bundle.mjs")) {
  const bundle = buildBundle();
  writeFileSync(new URL("../claim-check.mjs", import.meta.url), bundle);
  console.log(`bundle written: ${bundle.length} bytes`);
}
